def is_valid_year_month(s):
    parts = s.split('-')
    if len(parts) != 2:
        return False
    year_part, month_part = parts
    if len(year_part) != 4 or not year_part.isdigit():
        return False
    if len(month_part) != 2 or not month_part.isdigit():
        return False
    return 1 <= int(month_part) <= 12

