def business_days_between(date1, date2):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def day_of_year(y, m, d):
        lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m - 1]) + d
    def ordinal(date):
        y, m, d = date
        return 365 * (y - 1) + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400 + day_of_year(y, m, d)
    start = ordinal(date1)
    end = ordinal(date2)
    total = 0
    for o in range(start, end):
        if (o + 5) % 7 not in (5, 6):
            total += 1
    return total

